package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextFieldName
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen2Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    @Test
    public void testNextFieldName_SuccessLiteralMatch() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(json);

        // Move to start of object
        parser.nextToken(); 
        assertEquals(JsonToken.START_OBJECT, parser.currentToken());

        SerializableString target = new SerializedString("name");

        // nextFieldName should find "name", skip the colon, and return true
        boolean found = parser.nextFieldName(target);

        assertTrue("Should return true when field name matches", found);
        assertEquals("name", parser.currentName());
        // After nextFieldName, the parser should be positioned at the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value", parser.getText());
    }

    @Test
    public void testNextFieldName_MismatchName() throws IOException {
        String json = "{\"age\":30}";
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_OBJECT

        SerializableString target = new SerializedString("name");

        // Should return false because "age" != "name"
        boolean found = parser.nextFieldName(target);

        assertFalse("Should return false when field name does not match", found);
        // In Jackson, if it doesn't match, the token remains at the start of the mismatching name or value depending on implementation
        // Based on the code, if _isNextTokenNameMaybe returns false, it returns false.
    }

    @Test
    public void testNextFieldName_AlreadyAtFieldName() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "name"

        assertEquals(JsonToken.FIELD_NAME, parser.currentToken());

        // If current token is FIELD_NAME, the method calls _nextAfterName() and returns false
        boolean found = parser.nextFieldName(new SerializedString("name"));

        assertFalse("Should return false if current token is already FIELD_NAME", found);
    }

    @Test
    public void testNextFieldName_EndOfObject() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_OBJECT

        // The next thing after START_OBJECT is END_OBJECT
        // The code checks for INT_RCURLY (end of object)
        boolean found = parser.nextFieldName(new SerializedString("any"));

        assertFalse(found);
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_EndOfArray_Mismatched() throws IOException {
        // Testing the branch where i == INT_RBRACKET but we aren't in an array
        // We simulate this by calling nextFieldName when the context is an object but we encounter ']'
        String json = "{\"key\": [] ]"; // Invalid JSON to force mismatch
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "key"
        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // END_ARRAY

        // Now at ']', but we are still inside the object context
        try {
            parser.nextFieldName(new SerializedString("key"));
            fail("Should have thrown MismatchedInputException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_IncompleteToken() throws IOException {
        // Testing the _tokenIncomplete branch
        // This is hard to trigger via standard string parsing as the parser usually 
        // handles the state, but we can simulate a scenario where a string is left open
        // by using a custom parser or specific malformed input if possible.
        // For now, we ensure standard flow works.
        String json = "{\"a\":1}";
        JsonParser parser = factory.createParser(json);
        parser.nextToken(); // START_OBJECT

        assertTrue(parser.nextFieldName(new SerializedString("a")));
    }

    @Test
    public void testNextFieldName_AfterComma() throws IOException {
        String json = "{\"a\":1, \"b\":2}";
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(new SerializedString("a"));
        parser.nextToken(); // VALUE_1

        // Now we are at the comma or after the value. 
        // nextFieldName should skip the comma and find "b"
        boolean found = parser.nextFieldName(new SerializedString("b"));

        assertTrue(found);
        assertEquals("b", parser.currentName());
    }

    @Test
    public void testNextFieldName_EndOfStringInput() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // END_OBJECT

        // Now at EOF
        boolean found = parser.nextFieldName(new SerializedString("any"));
        assertFalse(found);
    }

    @Test
    public void testNextFieldName_NotAnObject() throws IOException {
        String json = "[1, 2, 3]";
        JsonParser parser = factory.createParser(json);

        parser.nextToken(); // START_ARRAY

        // nextFieldName called while in an array context (not an object)
        // Should trigger _nextTokenNotInObject
        try {
            parser.nextFieldName(new SerializedString("any"));
            fail("Should have thrown exception because not in object");
        } catch (IOException e) {
            // Expected
        }
    }
}
